package org.transittr.tests;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
public final class IettCheck extends Instrumentation {
 private Activity a;private volatile boolean measuring;private int peak,samples;
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private Object field(String name)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private void call(String name)throws Exception{Method m=a.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}
 private void set(String name,Object value)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);f.set(a,value);}
 private void report(String message){Bundle b=new Bundle();b.putString("stream",message+"\n");sendStatus(1,b);}
 private void query(final String stopCode,final String line,final String direction)throws Exception{runOnMainSync(new Runnable(){public void run(){try{call("stopTracking");set("city",1);set("screen",0);set("snapshot",null);a.getPreferences(0).edit().putString("track-direction:1",direction).commit();call("build");((EditText)field("stopInput")).setText(stopCode);((EditText)field("lineInput")).setText(line);((Button)field("start")).performClick();}catch(Exception e){throw new RuntimeException(e);}}});for(int i=0;i<300;i++){Thread.sleep(200);waitForIdleSync();if(field("snapshot")!=null)return;}throw new AssertionError("IETT query timeout");}
 private ArrayList rows(Object snapshot)throws Exception{return (ArrayList)snapshot.getClass().getField("rows").get(snapshot);}
 private void fixtures()throws Exception{ClassLoader cl=a.getClassLoader();Class<?> client=cl.loadClass("org.transittr.IettClient"),snapshot=cl.loadClass("org.transittr.JourneyData$Snapshot");Method arrivals=client.getMethod("arrivals",String.class,String.class),locations=client.getMethod("locations",String.class,String.class),combine=client.getMethod("combine",snapshot,snapshot,String.class);
  String raw="[{\"door_no\":\"A\",\"line_code\":\"500T\",\"route_code\":\"500T_G_D0\",\"stop_code\":224672,\"lat\":41,\"lng\":29,\"minutes_left\":3,\"last_location_time\":\"18:00:00\"},{\"door_no\":\"B\",\"line_code\":\"500T\",\"route_code\":\"500T_D_D0\",\"lat\":41.1,\"lng\":29.1,\"minutes_left\":null}]";
  Object eta=arrivals.invoke(null,raw,"");check(rows(eta).size()==2,"arrivals with valid GPS");Object first=rows(eta).get(0),second=rows(eta).get(1);check("3 dk".equals(first.getClass().getField("eta").get(first)),"real minutes");check("—".equals(second.getClass().getField("eta").get(second)),"null minutes not zero");check(first.getClass().getField("observedAt").getLong(first)==0,"time-only value has no fabricated date");
  String gps="{\"data\":[{\"bus_id\":\"A\",\"route_code\":\"500T_G_D0\",\"lat\":41,\"lng\":29,\"last_update_time\":\"2026-11-07T15:00:00Z\"},{\"bus_id\":\"B\",\"route_code\":\"500T_D_D0\",\"lat\":41.1,\"lng\":29.1,\"last_update_time\":null}]}";
  Object fleet=locations.invoke(null,gps,"500T");Calendar clock=Calendar.getInstance(TimeZone.getTimeZone("UTC"));clock.clear();clock.set(2026,10,7,15,0,0);check(rows(fleet).get(0).getClass().getField("observedAt").getLong(rows(fleet).get(0))==clock.getTimeInMillis(),"ISO UTC timestamp");check(rows(fleet).get(1).getClass().getField("observedAt").getLong(rows(fleet).get(1))==0,"null source timestamp");Object joined=combine.invoke(null,fleet,eta,"G");check(rows(joined).size()==1&&"3 dk".equals(rows(joined).get(0).getClass().getField("eta").get(rows(joined).get(0))),"join by vehicle and same route; direction filter");
  Object wrong=arrivals.invoke(null,raw.replace("500T_G_D0","500T_D_D0"),"");fleet=locations.invoke(null,gps,"500T");joined=combine.invoke(null,fleet,wrong,"G");Object mapVehicle=((ArrayList)joined.getClass().getField("mapRows").get(joined)).get(0);check("GPS".equals(mapVehicle.getClass().getField("eta").get(mapVehicle)),"wrong route cannot supply ETA");ArrayList stops=(ArrayList)client.getMethod("parseStops",String.class).invoke(null,"[{\"code\":224672,\"name\":\"Test\",\"lat\":41,\"lng\":29},{\"code\":1,\"lat\":0,\"lng\":0}]");check(stops.size()==1,"stop coordinate validation");report("IETT_FIXTURES_PASS=9");}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();Thread sampler=null;boolean pass=false;try{measuring=true;sampler=new Thread(new Runnable(){public void run(){while(measuring){Debug.MemoryInfo m=new Debug.MemoryInfo();Debug.getMemoryInfo(m);peak=Math.max(peak,m.getTotalPss());samples++;try{Thread.sleep(100);}catch(InterruptedException e){return;}}}});sampler.start();a=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();fixtures();query("224672","","");Object stop=field("snapshot");report("STOP_SOURCE="+stop.getClass().getField("source").get(stop));check(rows(stop).size()>0,"real stop GPS");boolean minutes=false;for(Object v:rows(stop))if(v.getClass().getField("etaSeconds").getLong(v)>=0)minutes=true;check(minutes,"real stop minutes");check(((LinearLayout)field("bottomRows")).getChildCount()==rows(stop).size(),"all arrivals rendered");check(((LinearLayout)field("bottomRows")).getParent() instanceof ScrollView,"vertical scroll container");final ScrollView departures=(ScrollView)((LinearLayout)field("bottomRows")).getParent();runOnMainSync(new Runnable(){public void run(){departures.fullScroll(android.view.View.FOCUS_DOWN);}});Thread.sleep(400);check(departures.getScrollY()>0,"other lines reachable by scrolling");report("DEPARTURE_SCROLL_PASS=true");report("CAPTURE=IETT_MORE_LINES");Thread.sleep(6000);runOnMainSync(new Runnable(){public void run(){departures.fullScroll(android.view.View.FOCUS_UP);}});report("IETT_STOP_PASS=true; VEHICLES="+rows(stop).size());report("CAPTURE=IETT_STOP_MAP");Thread.sleep(6000);query("224672","500T","G");Object unserved=field("snapshot");check(unserved.getClass().getField("stopServed").getInt(unserved)==0,"500T does not serve Kadikoy Carsi");check(rows(unserved).isEmpty(),"fleet GPS cannot replace stop ETA rows");check(((Integer)unserved.getClass().getMethod("positionCount").invoke(unserved)).intValue()>0,"unserved stop still allows fleet map");report("IETT_UNSERVED_STOP_PASS=true");report("CAPTURE=IETT_UNSERVED_LINE");Thread.sleep(6000);query("205471","500T","G");Object line=field("snapshot");check(rows(line).size()>0,"specific line has real stop arrivals");boolean lineMinutes=false;for(Object v:rows(line))if(v.getClass().getField("etaSeconds").getLong(v)>=0&&!"GPS".equals(v.getClass().getField("eta").get(v)))lineMinutes=true;check(lineMinutes,"specific line displays minutes");ArrayList fleet=(ArrayList)line.getClass().getField("mapRows").get(line);check(fleet.size()>0,"real line GPS");for(Object v:fleet)check(((String)v.getClass().getField("routeCode").get(v)).contains("_G_"),"live direction filter");int stops=((ArrayList)line.getClass().getField("busStops").get(line)).size();check(stops>0,"real line stops");report("IETT_LINE_PASS=true; ARRIVALS="+rows(line).size()+"; VEHICLES="+fleet.size()+"; STOPS="+stops);report("CAPTURE=IETT_LINE_MAP");Thread.sleep(6000);pass=true;result.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; IETT_STOP_AND_LINE=true; SPECIFIC_LINE_MINUTES=true; UNSERVED_STOP=true; ALL_ARRIVALS_SCROLL=true; PEAK_PSS_KIB="+peak+"; SAMPLES="+samples+"\n");}catch(Throwable e){java.io.StringWriter out=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(out));result.putString("stream","FAIL API="+Build.VERSION.SDK_INT+"\n"+out);}finally{measuring=false;if(sampler!=null)sampler.interrupt();}finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
